# PTX source for a naive FP16 GEMM (C = A @ B) on sm_80
PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry gemm_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr
)
{
    // thread indices
    .reg .s32 %tid_x, %tid_y;
    .reg .s32 %bid_x, %bid_y;
    .reg .s32 %row, %col;

    mov.u32 %tid_x, %tid.x;
    mov.u32 %tid_y, %tid.y;
    mov.u32 %bid_x, %ctaid.x;
    mov.u32 %bid_y, %ctaid.y;

    // compute global row and column (M=256, N=256)
    mul.lo.s32 %row, %bid_x, 16;
    add.s32 %row, %row, %tid_x;    // row index 0..255
    mul.lo.s32 %col, %bid_y, 16;
    add.s32 %col, %col, %tid_y;    // col index 0..255

    // load base pointers
    .reg .u64 %A, %B, %C;
    ld.param.u64 %A, [A_ptr];
    ld.param.u64 %B, [B_ptr];
    ld.param.u64 %C, [C_ptr];

    // constants
    .reg .s32 %K;
    mov.s32 %K, 524288;            // K = 131072*4

    // accumulator in FP32
    .reg .f32 %c;
    mov.f32 %c, 0f00000000;

    // loop variable
    .reg .s32 %k;
    mov.s32 %k, 0;

    // registers for loads and conversions
    .reg .f16 %a_h, %b_h;
    .reg .f32 %a_f, %b_f;

    // temporary registers for address calculations
    .reg .u64 %addr;
    .reg .u64 %tmp64;
    .reg .s32 %tmp32;
    .reg .pred %p;

LOOP:
    // ---- Load A[row, k] ----
    // offset = (row * K + k) * 2
    mul.wide.s32 %tmp64, %row, %K;          // row * K
    add.s32 %tmp32, %k, 0;
    mul.wide.s32 %addr, %tmp32, 2;          // k * 2
    add.u64 %addr, %tmp64, %addr;           // row*K*2 + k*2
    add.u64 %addr, %A, %addr;               // base + offset
    ld.global.f16 %a_h, [%addr];

    // ---- Load B[k, col] ----
    // offset = (k * N + col) * 2, N = 256
    mul.wide.s32 %tmp64, %k, 256;           // k * N
    add.s32 %tmp32, %col, 0;
    mul.wide.s32 %addr, %tmp32, 2;          // col * 2
    add.u64 %addr, %tmp64, %addr;           // k*N*2 + col*2
    add.u64 %addr, %B, %addr;               // base + offset
    ld.global.f16 %b_h, [%addr];

    // Convert to FP32
    cvt.f32.f16 %a_f, %a_h;
    cvt.f32.f16 %b_f, %b_h;

    // Accumulate
    fma.rn.f32 %c, %a_f, %b_f, %c;

    // increment k
    add.s32 %k, %k, 1;
    setp.lt.s32 %p, %k, %K;
    @%p bra LOOP;

    // ---- Store result C[row, col] ----
    // convert accumulator to half
    .reg .f16 %c_h;
    cvt.f16.f32 %c_h, %c;

    // offset = (row * N + col) * 2, N = 256
    mul.wide.s32 %tmp64, %row, 256;         // row * N
    add.s32 %tmp32, %col, 0;
    mul.wide.s32 %addr, %tmp32, 2;          // col * 2
    add.u64 %addr, %tmp64, %addr;           // row*N*2 + col*2
    add.u64 %addr, %C, %addr;               // base + offset
    st.global.f16 [%addr], %c_h;

    ret;
}
'''

# --------------------------------------------------------------
# PyTorch model that uses the above PTX kernel
import torch
import torch.nn as nn

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        # load PTX module via the provided harness
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        A: (M, K) fp16 tensor on CUDA
        B: (K, N) fp16 tensor on CUDA
        Returns C: (M, N) fp16 tensor on CUDA
        """
        M, K = A.shape
        K2, N = B.shape
        assert K == K2, "Inner dimensions must match"
        C = torch.empty((M, N), dtype=torch.float16, device=A.device)

        # launch configuration (16x16 threads per block)
        grid = (M // 16, N // 16, 1)
        block = (16, 16, 1)

        # arguments are raw device pointers
        args = [A.data_ptr(), B.data_ptr(), C.data_ptr()]

        # launch the kernel via the harness
        ptx_launch(self.module, "gemm_kernel", grid, block, args)

        return C
